/** Rebuilds one workspace/day atomically under its routing fence and rollup lock. */
async function rollupWorkspace(
  pool: Pool,
  workspaceId: string,
  day: string,
  preserveFullerSnapshot: boolean,
): Promise<number> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await setCurrentWorkspaceRoutingEpoch(client, workspaceId);
    await client.query("SELECT pg_advisory_xact_lock(hashtextextended($1, 0))", [
      `skillplane-rollup:${workspaceId}:${day}`,
    ]);
    const source = await client.query<{
      event_count: string;
      latest_event_at: Date | null;
    }>(
      `SELECT count(*)::text AS event_count, max(occurred_at) AS latest_event_at
         FROM audit_events
        WHERE workspace_id = $1
          AND ${utcDayPredicate(2, "occurred_at")}`,
      [workspaceId, day],
    );
    const row = source.rows[0];
    const eventCount = Number(row?.event_count ?? 0);
    if (preserveFullerSnapshot) {
      const existing = await client.query<{ source_event_count: string }>(
        `SELECT source_event_count
           FROM analytics_rollup_runs
          WHERE workspace_id = $1 AND day = $2::date`,
        [workspaceId, day],
      );
      const preservedEventCount = Number(existing.rows[0]?.source_event_count ?? 0);
      if (existing.rows[0] && preservedEventCount >= eventCount) {
        await client.query("COMMIT");
        return preservedEventCount;
      }
    }
    await client.query(
      "DELETE FROM analytics_daily_dimensions WHERE workspace_id = $1 AND day = $2",
      [workspaceId, day],
    );

