import { zipSync, type Zippable } from "fflate";
import {
  canonicalSkillJson,
  stableJson,
  type BundleManifest,
  type CanonicalBundle,
  type SkillFileManifestEntry,
  type SkillJson,
} from "./manifest.js";
import {
  bundlePathCollisionKey,
  bytewisePathCompare,
  normalizeBundlePath,
} from "./paths.js";
import {
  BUNDLE_LIMITS,
  BundleValidationError,
  mediaTypeForPath,
  sha256Hex,
  validateBundleArchive,
} from "./validate.js";

const CANONICAL_MTIME = new Date("1980-01-01T00:00:00.000Z");
const REGULAR_FILE_MODE = 0o100644 << 16;
const encoder = new TextEncoder();

export async function canonicalizeBundle(
  archiveBytes: Uint8Array,
): Promise<CanonicalBundle> {
  const validated = await validateBundleArchive(archiveBytes);
  const canonicalFiles = new Map(validated.files);
  const normalizedSkill = canonicalSkillJson({
    ...validated.skill,
    files: validated.fileManifest,
  });
  canonicalFiles.set("skill.json", encoder.encode(`${stableJson(normalizedSkill)}\n`));

  const paths = [...canonicalFiles.keys()].sort(bytewisePathCompare);
  const zippable: Zippable = {};
  for (const path of paths) {
    const content = canonicalFiles.get(path);
    if (!content) continue;
    zippable[path] = [
      content,
      {
        attrs: REGULAR_FILE_MODE,
        level: 9,
        mtime: CANONICAL_MTIME,
        os: 3,
      },
    ];
  }
  const bytes = zipSync(zippable, {
    attrs: REGULAR_FILE_MODE,
    level: 9,
    mtime: CANONICAL_MTIME,
    os: 3,
  });
  if (bytes.byteLength > BUNDLE_LIMITS.compressedBytes) {
    throw new BundleValidationError(
      "SKILL_BUNDLE_TOO_LARGE",
      "Canonical bundle exceeds 10 MiB",
    );
  }
  const digestHex = await sha256Hex(bytes);
  const files: SkillFileManifestEntry[] = [];
  for (const path of paths) {
    const content = canonicalFiles.get(path);
    if (!content) continue;
    files.push({
      path,
      sha256: await sha256Hex(content),
      byteSize: content.byteLength,
      mediaType: mediaTypeForPath(path),
    });
  }
  const expandedByteSize = files.reduce((total, file) => total + file.byteSize, 0);
  const digest = `sha256:${digestHex}` as const;
  const manifest: BundleManifest = {
    formatVersion: normalizedSkill.formatVersion,
    digest,
    byteSize: bytes.byteLength,
    expandedByteSize,
    fileCount: files.length,
    files,
  };
  return {
    bytes,
    digest,
    manifest,
    skill: normalizedSkill,
    files: canonicalFiles,
  };
}

/**
 * Builds and validates a canonical bundle from an already-extracted file set.
 * `skill.json` is always regenerated from the immutable skill identity and the
 * resulting inventory, so a caller cannot smuggle metadata changes through a
 * file amendment.
 */
export async function canonicalizeBundleFiles(options: {
  readonly skill: SkillJson extends infer S
    ? S extends SkillJson
      ? Omit<S, "files">
      : never
    : never;
  readonly files: ReadonlyMap<string, Uint8Array>;
}): Promise<CanonicalBundle> {
  const contentFiles = new Map<string, Uint8Array>();
  const collisionKeys = new Set<string>();
  for (const [rawPath, rawContent] of options.files) {
    const path = normalizeBundlePath(rawPath);
    if (path === "skill.json") continue;
    const collisionKey = bundlePathCollisionKey(path);
    if (collisionKeys.has(collisionKey)) {
      throw new BundleValidationError(
        "SKILL_PATH_DUPLICATE",
        "Bundle contains duplicate case-folded paths",
      );
    }
    collisionKeys.add(collisionKey);
    const content = new Uint8Array(rawContent.byteLength);
    content.set(rawContent);
    contentFiles.set(path, content);
  }
  const manifestFiles: SkillFileManifestEntry[] = [];
  for (const [path, content] of contentFiles) {
    manifestFiles.push({
      path,
      sha256: await sha256Hex(content),
      byteSize: content.byteLength,
      mediaType: mediaTypeForPath(path),
    });
  }
  manifestFiles.sort((left, right) => bytewisePathCompare(left.path, right.path));
  const skill = canonicalSkillJson({ ...options.skill, files: manifestFiles });
  const archiveFiles = new Map(contentFiles);
  archiveFiles.set("skill.json", encoder.encode(`${stableJson(skill)}\n`));
  const zippable: Zippable = {};
  for (const path of [...archiveFiles.keys()].sort(bytewisePathCompare)) {
    const content = archiveFiles.get(path);
    if (!content) continue;
    zippable[path] = [
      content,
      {
        attrs: REGULAR_FILE_MODE,
        level: 9,
        mtime: CANONICAL_MTIME,
        os: 3,
      },
    ];
  }
  return canonicalizeBundle(
    zipSync(zippable, {
      attrs: REGULAR_FILE_MODE,
      level: 9,
      mtime: CANONICAL_MTIME,
      os: 3,
    }),
  );
}

import fc from "fast-check";
import { describe, expect, it } from "vitest";
import goldenDigests from "../tests/fixtures/canonical-digests.json" with { type: "json" };
import { createTestBundle } from "../tests/support/bundle-fixture.js";
import { canonicalizeBundle } from "./canonicalize.js";

describe("canonical bundle", () => {
  it("matches the versioned canonical fixture digests", async () => {
    const minimal = await canonicalizeBundle(
      await createTestBundle(
        { "SKILL.md": "# Minimal skill\n" },
        { name: "Minimal skill", slug: "minimal-skill" },
      ),
    );
    const portable = await canonicalizeBundle(
      await createTestBundle(
        {
          "SKILL.md": "# Pull request review\n\nReview for correctness.\n",
          "references/checklist.md": "- Tests\n- Security\n",
          "scripts/check.sh": "#!/bin/sh\nexit 0\n",
        },
        { name: "PR review", slug: "pr-review" },
      ),
    );
    expect({
      minimal: { digest: minimal.digest, byteSize: minimal.bytes.byteLength },
      portable: { digest: portable.digest, byteSize: portable.bytes.byteLength },
    }).toEqual(goldenDigests);
  });

  it("produces byte-identical output across ordering and timestamps", async () => {
    const files = {
      "SKILL.md": "# Pull request review\n\nReview for correctness.\n",
      "references/checklist.md": "- Tests\n- Security\n",
      "scripts/check.sh": "#!/bin/sh\nexit 0\n",
    };
    const first = await createTestBundle(files, {
      slug: "pr-review",
      name: "PR review",
      order: ["scripts/check.sh", "SKILL.md", "references/checklist.md"],
      mtime: new Date("2020-01-02T04:06:00Z"),
    });
    const second = await createTestBundle(files, {
      slug: "pr-review",
      name: "PR review",
      order: ["references/checklist.md", "SKILL.md", "scripts/check.sh"],
      mtime: new Date("2026-07-25T06:00:00Z"),
    });
    const a = await canonicalizeBundle(first);
    const b = await canonicalizeBundle(second);
    expect(a.bytes).toEqual(b.bytes);
    expect(a.digest).toBe(b.digest);
    expect(a.manifest.files.map((file) => file.path)).toEqual([
      "SKILL.md",
      "references/checklist.md",
      "scripts/check.sh",
      "skill.json",
    ]);
  });

  it("is idempotent and preserves every declared file digest", async () => {
    const input = await createTestBundle({
      "SKILL.md": "# One\n",
      "assets/data.txt": "data",
    });
    const first = await canonicalizeBundle(input);
    const second = await canonicalizeBundle(first.bytes);
    expect(second.bytes).toEqual(first.bytes);
    expect(second.manifest).toEqual(first.manifest);
  });

  it("holds determinism over generated portable bundle inventories", async () => {
    await fc.assert(
      fc.asyncProperty(
        fc.array(
          fc.record({
            body: fc.string({ maxLength: 120 }),
            suffix: fc.integer({ min: 0, max: 20 }),
          }),
          { minLength: 1, maxLength: 8 },
        ),
        async (values) => {
          const deduplicated = new Map<number, string>();
          for (const value of values) deduplicated.set(value.suffix, value.body);
          const files: Record<string, string> = {
            "SKILL.md": "# Generated skill\n",
          };
          for (const [suffix, body] of deduplicated) {
            files[`references/file-${suffix}.md`] = body;
          }
          const forward = Object.keys(files);
          const reverse = [...forward].reverse();
          const first = await canonicalizeBundle(
            await createTestBundle(files, {
              order: forward,
              mtime: new Date("2010-01-01T00:00:00Z"),
            }),
          );
          const second = await canonicalizeBundle(
            await createTestBundle(files, {
              order: reverse,
              mtime: new Date("2030-12-30T00:00:00Z"),
            }),
          );
          expect(second.bytes).toEqual(first.bytes);
          expect(second.digest).toBe(first.digest);
        },
      ),
      { numRuns: 75, seed: 20_260_725 },
    );
  });
});

