  "",
  '<unknown-widget id="keep"></unknown-widget>',
  "",
].join("\n");

describe("Skillplane Markdown profile", () => {
  it("names the shared authoring and rendering profile", () => {
    expect(SKILLPLANE_MARKDOWN_PROFILE_NAME).toBe("skillplane.markdown.v1");
    expect(inspectSkillplaneMarkdown("# Title\n").profile).toBe(
      SKILLPLANE_MARKDOWN_PROFILE_NAME,
    );
  });

  it("renders Markdown while neutralizing raw HTML and unsafe URLs", () => {
    const html = renderSafeMarkdown(SECURITY_FIXTURE);
    expect(html).toContain("<h1>Safe</h1>");
    expect(html).toContain("&lt;script&gt;");
    expect(html).not.toContain("<script");
    expect(html).not.toContain("javascript:");
    expect(html).not.toContain("data:text");
    expect(html).toContain('rel="noreferrer noopener"');
  });

  it("keeps preview and read-only rendering on the same profile", () => {
    const html = renderSafeMarkdown(SECURITY_FIXTURE);
    expect(html).toBe(renderSkillplaneMarkdown(SECURITY_FIXTURE).html);
    expect(html).toContain("https://example.com");
  });

  it("preserves untouched source and unsupported syntax", () => {
    const parsed = parseSkillplaneMarkdown(PRESERVATION_FIXTURE);
    const serialized = serializeMarkdown({
      document: parsed.document,
      originalSource: PRESERVATION_FIXTURE,
      options: SKILLPLANE_MARKDOWN_OPTIONS,
    });
    expect(parsed.source).toBe(PRESERVATION_FIXTURE);
    expect(serialized.markdown).toBe(PRESERVATION_FIXTURE);
    expect(serialized.preservation.exactUntouched).toBe(true);
    expect(inspectSkillplaneMarkdown(PRESERVATION_FIXTURE).html).toContain(
      "unknown-widget",
    );
    expect(
      parsed.diagnostics.some((entry) => entry.code === "MDFN_RAW_HTML_DISABLED"),
    ).toBe(true);
    expect(() => renderSkillplaneMarkdown(PRESERVATION_FIXTURE)).not.toThrow();
  });

  it("permits safe relative, fragment, and mailto links", () => {
    const html = renderSafeMarkdown(
      "[root](/docs) [rel](./guide.md) [guide](guide.md) [frag](#section) [mail](mailto:ops@example.com)",
    );
    expect(html).toContain('href="/docs"');
    expect(html).toContain('href="./guide.md"');
    expect(html).toContain('href="guide.md"');
    expect(html).toContain('href="#section"');
    expect(html).toContain('href="mailto:ops@example.com"');
    expect(html).not.toContain('href="//example.com"');
  });

  it("rejects protocol-relative URLs", () => {
    const html = renderSafeMarkdown("[bad](//example.com/secret)");
    expect(html).not.toContain("//example.com/secret");
  });
});

import { defaultExtensions } from "@mdfn/extensions";
import {
  parseMarkdown,
  type MarkdownOptions,
  type MarkdownParseResult,
} from "@mdfn/markdown";
import { renderHtml, type RenderPolicy, type RenderResult } from "@mdfn/render";

export const SKILLPLANE_MARKDOWN_PROFILE_NAME = "skillplane.markdown.v1" as const;
export const SKILLPLANE_MARKDOWN_PROFILE_VERSION = "1.0.0" as const;

export const SKILLPLANE_MARKDOWN_OPTIONS: MarkdownOptions = Object.freeze({
  dialect: "gfm",
  allowRawHtml: false,
  extensions: defaultExtensions,
});

export const SKILLPLANE_RENDER_POLICY: RenderPolicy = Object.freeze({
  rawHtml: Object.freeze({ enabled: false }),
  links: Object.freeze({
    allowedSchemes: Object.freeze(["http", "https", "mailto"]),
    allowRelative: true,
    allowProtocolRelative: false,
    externalTarget: "_blank",
    externalRel: "noreferrer noopener",
  }),
  images: Object.freeze({
    allowedSchemes: Object.freeze(["http", "https"]),
    allowRelative: true,
    loading: "lazy",
    decoding: "async",
  }),
  extensions: defaultExtensions,
});

export interface SkillplaneMarkdownInspection {
  readonly profile: typeof SKILLPLANE_MARKDOWN_PROFILE_NAME;
  readonly source: string;
  readonly html: string;
  readonly diagnostics: MarkdownParseResult["diagnostics"];
  readonly renderDiagnostics: RenderResult["diagnostics"];
}

function hasErrorDiagnostics(
  diagnostics: readonly { readonly severity: string }[],
): boolean {
  return diagnostics.some((entry) => entry.severity === "error");
}

function firstErrorMessage(
  diagnostics: readonly { readonly severity: string; readonly message: string }[],
  fallback: string,
): string {
  return diagnostics.find((entry) => entry.severity === "error")?.message ?? fallback;
}

export function parseSkillplaneMarkdown(source: string): MarkdownParseResult {
  return parseMarkdown(source, SKILLPLANE_MARKDOWN_OPTIONS);
}

export function renderSkillplaneMarkdown(source: string): RenderResult {
  const parsed = parseSkillplaneMarkdown(source);
  if (hasErrorDiagnostics(parsed.diagnostics)) {
    throw new Error(
      firstErrorMessage(
        parsed.diagnostics,
        "Markdown parse produced error diagnostics",
      ),
    );
  }
  const rendered = renderHtml(parsed.document, SKILLPLANE_RENDER_POLICY);
  if (hasErrorDiagnostics(rendered.diagnostics)) {
    throw new Error(
      firstErrorMessage(
        rendered.diagnostics,
        "Markdown render produced error diagnostics",
      ),
    );
  }
  return rendered;
}

export function inspectSkillplaneMarkdown(
  source: string,
): SkillplaneMarkdownInspection {
  const parsed = parseSkillplaneMarkdown(source);
  const rendered = renderHtml(parsed.document, SKILLPLANE_RENDER_POLICY);
  return {
    profile: SKILLPLANE_MARKDOWN_PROFILE_NAME,
    source,
    html: rendered.html,
    diagnostics: parsed.diagnostics,
    renderDiagnostics: rendered.diagnostics,
  };
}

import { renderSkillplaneMarkdown } from "./markdown-profile.js";

export function renderSafeMarkdown(markdown: string): string {
  return renderSkillplaneMarkdown(markdown).html;
}

